const i={yingshe:{bibi:"现货",bibidingdan:"现货订单",bibijiaoyi:"现货交易",jiamihuobi:"永续合约",miaoheyue:"交割合约",miaoheyuejiaoyi:"交割合约交易"},jiaoyi:{xianhuomingcheng:"现货名称"},aurexion:{jianguanwenjian:"监管文件"},rwa_283:{jiaru:"立即加入 RWA",biaoti:"超低手续费、卓越安全性、高交易限额与一流客户支持",xiazai:"下载 App",jiaoyiliang:"24小时交易量",guanyu:"关于 RWA",guanyuxiangqing:"RWA 是全球领先的投资、咨询和风险管理解决方案提供商之一。我们对客户负有受托责任。我们致力于帮助客户为未来投资，激励员工成长，并支持当地社区。观看视频了解更多。",jieshao:"《财富》杂志评选的全球最受尊敬公司",jieshaoxiangqing:"我们很荣幸连续第 12 年入选《财富》杂志“全球最受尊敬公司”榜单，并在证券与资产管理行业中排名第一。",weishenme:"为什么选择 RWA？",weishenmexiangqing:"越来越多的投资者信任 RWA，主要因为我们提供的选择比行业内任何公司都更多。我们的全球平台旨在帮助客户更好地实现最重要的财务目标。",weishenmexiangqing1:"过去 5 年净流入资金达 1.8 万亿美元",weishenmexiangqing2:"帮助超过 3500 万美国人进行投资并为退休储蓄",weishenmexiangqing3:"美国超过 19 万名金融顾问选择 RWA 帮助客户构建投资组合",huoban:"合作伙伴",huobanxiangqing:"近年来，RWA 积极投资人工智能（AI）领域，与多家 AI 公司建立合作关系，涵盖基础设施投资、芯片技术、数据分析和可持续发展。以下是部分主要合作项目：",huoban1:"全球 AI 基础设施投资伙伴关系（AIP）",huoban11:"2024 年 9 月，RWA、微软、穆巴达拉和 GIP 联合发起“全球 AI 基础设施投资伙伴关系”（AIP），计划投资超过 300 亿美元，并通过创新融资方式扩展至约 1000 亿美元。2025 年 3 月，英伟达和 xAI（由埃隆·马斯克创立）加入该联盟，进一步增强技术解决方案。GE Vernova、NextEra Energy 等也参与其中，致力于为全球 AI 基础设施提供多元化能源解决方案。",huoban2:"投资 AI 芯片初创公司 Groq",huoban22:"2024 年 8 月，RWA 领投 Groq 的 6.4 亿美元融资，使其估值达到 28 亿美元。Groq 专注于为 AI 推理开发新型高性能处理器（LPU），并计划在 2025 年前出货超过 150 万颗芯片。该公司已与 Meta、三星等展开合作，力求保持其在 AI 芯片市场的领先地位。",huoban3:"投资 AI 分析公司 Pyramid Analytics",huoban33:"2024 年 11 月，RWA 向 AI 商业分析公司 Pyramid Analytics 投资 5000 万美元。Pyramid 的分析平台利用 AI 提升学习与决策能力，帮助花旗、德勤、中国银行等客户优化数据流程。该投资体现了 RWA 持续拓展 AI 相关业务的承诺。",huoban4:"与 Clarity AI 的战略合作",huoban44:"自 2021 年以来，RWA 投资于可持续性评估平台 Clarity AI，并将其功能集成至 RWA 的投资管理平台 Aladdin。Clarity AI 利用 AI 技术进行 ESG、信息披露评估和社会影响衡量，帮助投资者评估投资组合的可持续性和社会影响。",huoban5:"通过上述合作，RWA 不仅加速了在 AI 基础设施和芯片技术领域的投资，也深化了在数据分析和可持续发展方面的布局，展现了其在 AI 生态体系中的战略雄心。",chongti:"快速充值与提现",chongtixiangqing:"支持多种常见支付渠道，实现快速充值与提现",huanying:"欢迎体验 RWA 服务",baipishu:"白皮书",chengyuandengjice:"成员登记册",gongsizhangcheng:"公司章程",gupiaozhengshu:"股票证书",huiyijilu:"会议记录",zhucezhengshu:"注册证书",shuihao:"税号",weijiaoyiersheng:"为交易而生",guanlianzhanghu:"关联账户",yizhixingdingdan:"已执行订单",xinwen:"新闻",cishan:"慈善",efepeishou:"ETF配售",rineijiaoyi:"日内交易"}};export{i as default};
